typedef unsigned long long U;extern void*calloc(unsigned long,unsigned long);extern void free(void*);extern int printf(const char*,...);
int run(int n,int d){int E=n*(n-1)/2;U circ[100];int nc=0;for(U v=0;v<(1ull<<n);v++)if(__builtin_popcountll(v)==d+2){U x=0;int e=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,e++)if((v>>i&1)&&(v>>j&1))x|=1ull<<e;circ[nc++]=x;}U us[10000]={0};int ks[10000]={0},num=1;for(int h=0;h<num;h++)for(int c=0;c<nc;c++)if((circ[c]&~us[h])!=0){U x=us[h]|circ[c];int j;for(j=0;j<num&&us[j]!=x;j++);if(j==num){if(num==10000)return 99;us[num]=x;ks[num++]=ks[h]+1;}else if(ks[j]<ks[h]+1){ks[j]=ks[h]+1;h=-1;break;}}U total=1ull<<E;unsigned char*r=calloc(total,1);for(U s=0;s<total;s++){int best=__builtin_popcountll(s);for(int j=1;j<num;j++){int k=__builtin_popcountll(s|us[j])-ks[j];if(k<best)best=k;}r[s]=best;}U failures=0,checks=0;for(U s=0;s<total;s++)for(int i=0;i<E;i++)if(!(s>>i&1))for(int j=i+1;j<E;j++)if(!(s>>j&1)){checks++;if(r[s]+r[s|(1ull<<i)|(1ull<<j)]>r[s|(1ull<<i)]+r[s|(1ull<<j)]){if(!failures)printf("witness %llu %d %d\n",s,i,j);failures++;}}printf("n %d d %d circuits %d reachable_unions %d subsets %llu full_rank %d submod_checks %llu failures %llu\n",n,d,nc,num,total,r[total-1],checks,failures);free(r);return 0;}
